const out = [];
for (const it of $('Outreach webhook').all()) {
  const b = it.json.body || it.json;
  const t = String(b.event_type || '');
  let provider = null, type = null, emails = [], at = null, gm = null;
  const detail = {source_event: t};
  if (/^[A-Z_]+$/.test(t)) {
    provider = 'smartlead';
    const m = {EMAIL_SENT: 'sent', FIRST_EMAIL_SENT: 'sent', EMAIL_REPLY: 'reply', EMAIL_BOUNCE: 'bounce', LEAD_UNSUBSCRIBED: 'unsubscribe'};
    type = m[t] || null;
    if (t === 'LEAD_CATEGORY_UPDATED') {
      const s = String((b.lead_data && b.lead_data.category && b.lead_data.category.sentiment_type) || '').toLowerCase();
      type = s === 'positive' ? 'positive' : s === 'negative' ? 'negative' : 'neutral';
      detail.category = typeof b.category === 'string' ? b.category : null;
    }
    emails = [b.lead_email, b.to_email, b.from_email].filter(Boolean);
    at = b.time_sent || b.time_replied || b.event_timestamp || null;
    const cf = b.lead_data && b.lead_data.custom_fields;
    gm = (cf && !Array.isArray(cf) && cf.gm_lead_id) || null;
  } else if (t) {
    provider = 'instantly';
    const m = {email_sent: 'sent', reply_received: 'reply', email_bounced: 'bounce', lead_unsubscribed: 'unsubscribe', lead_interested: 'positive', lead_not_interested: 'negative'};
    type = m[t] || null;
    emails = [b.lead_email].filter(Boolean);
    at = b.timestamp || null;
    gm = b.gm_lead_id || null;
  }
  if (!provider || !type) continue;
  const ids = emails.map(e => String(e).toLowerCase()).sort();
  emails = ids;
  const key = [b.campaign_id || '', ids.join('+'), type, at || detail.category || ''].join('|');
  detail.campaign = b.campaign_name || null;
  out.push({json: {provider, event_type: type, dedupe_key: key, campaign_id: b.campaign_id == null ? null : String(b.campaign_id), event_time: at, emails, gm_lead_id: gm, detail}});
}
return out;
